685	  private _renderMainScene(skipPostProcessing: boolean): void {
686	    if (!this._renderer) return;
687	    this._backgroundManager?.render();
688	    if (skipPostProcessing || !this._postProcessor) {
689	      this._renderer.render?.(this._scene.three, this._camera);
690	      return;
691	    }
692	    try {
693	      this._postProcessor.render(this._scene.getBloomRoots(), this._lastDelta);
694	    } catch (error) {
695	      if (!this._didWarnPostProcessingFallback) {
696	        this._didWarnPostProcessingFallback = true;
697	      }
698	      this._renderer.render?.(this._scene.three, this._camera);
699	    }
700	  }
