707	  private _prepareTexture(texture: THREE.Texture): void {
708	    if (!(this._renderer instanceof THREE.WebGLRenderer)) return;
709	    const renderer = this._renderer as THREE.WebGLRenderer & {
710	      initTexture?: (map: THREE.Texture) => void;
711	    };
712	    renderer.initTexture?.(texture);
713	  }
