340	    const start = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowStart);
341	    const end = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowEnd);
342	    if (end <= start) return progress;
343	    if (progress <= start) return 0;
344	    if (progress >= end) return 1;
345	    return (progress - start) / (end - start);
346	  }
