481	  private _applyMainWhyShowcaseState(
482	    titleLayers: readonly HTMLElement[],
483	    ring: HTMLElement,
484	    cards: readonly HTMLElement[],
485	    progress: number,
486	  ): void {
487	    const cardCount = Math.max(cards.length, 1);
488	    const spawnProgress = this._easeOutCubic(
489	      Helpers.remap01(progress, 0, MAIN_WHY_SHOWCASE.spawnEnd),
490	    );
491	    const mergeProgress = this._easeInOutCubic(
492	      Helpers.remap01(
493	        progress,
494	        MAIN_WHY_SHOWCASE.cardRevealWindowEnd,
495	        MAIN_WHY_SHOWCASE.mergeEnd,
496	      ),
497	    );
498	    const scatterProgress = this._easeOutCubic(
499	      Helpers.remap01(
500	        progress,
501	        MAIN_WHY_SHOWCASE.mergeEnd,
502	        MAIN_WHY_SHOWCASE.scatterEnd,
503	      ),
504	    );
505	
506	    const titleRevealOpacity = Helpers.lerp(
507	      MAIN_WHY_SHOWCASE.titleOpacityStart,
508	      MAIN_WHY_SHOWCASE.titleOpacityEnd,
509	      spawnProgress,
510	    );
511	    const titleOpacity = Helpers.lerp(
512	      titleRevealOpacity,
513	      MAIN_WHY_SHOWCASE.titleExitOpacity,
514	      scatterProgress,
515	    );
516	    const titlePeakScale = Helpers.lerp(
517	      MAIN_WHY_SHOWCASE.titleScaleStart,
518	      MAIN_WHY_SHOWCASE.titleScalePeak,
519	      Math.max(spawnProgress, mergeProgress),
520	    );
521	    const titleScale = Helpers.lerp(
522	      titlePeakScale,
523	      MAIN_WHY_SHOWCASE.titleScaleEnd,
524	      scatterProgress,
525	    );
526	    const titleY = Helpers.lerp(
527	      MAIN_WHY_SHOWCASE.titleYOffsetPx,
528	      0,
529	      spawnProgress,
530	    ) + Helpers.lerp(0, MAIN_WHY_SHOWCASE.titleExitYOffsetPx, scatterProgress);
531	
532	    const titleTransform = `translate3d(0, ${titleY}px, 0) scale(${titleScale})`;
533	    titleLayers.forEach((titleLayer) => {
534	      titleLayer.style.opacity = String(titleOpacity);
535	      titleLayer.style.transform = titleTransform;
536	    });
537	
538	    const ringOpacity =
539	      MAIN_WHY_SHOWCASE.ringOpacityMax * Math.max(spawnProgress, mergeProgress);
540	    const ringScale = Helpers.lerp(
541	      MAIN_WHY_SHOWCASE.ringScaleStart,
542	      MAIN_WHY_SHOWCASE.ringScaleEnd,
543	      Math.max(spawnProgress, scatterProgress),
544	    );
545	    ring.style.opacity = String(ringOpacity);
546	    ring.style.transform = `translate3d(-50%, -50%, 0) scale(${ringScale})`;
547	
548	    cards.forEach((card, index) => {
549	      const pose = MAIN_WHY_SHOWCASE.cardPoses[index];
550	      if (!pose) return;
551	      const revealStart =
552	        Helpers.lerp(
553	          MAIN_WHY_SHOWCASE.cardRevealWindowStart,
554	          MAIN_WHY_SHOWCASE.cardRevealWindowEnd,
555	          index / cardCount,
556	        );
557	      const revealEnd =
558	        Helpers.lerp(
559	          MAIN_WHY_SHOWCASE.cardRevealWindowStart,
560	          MAIN_WHY_SHOWCASE.cardRevealWindowEnd,
561	          (index + 1) / cardCount,
562	        );
563	      const cardRevealProgress = this._easeOutCubic(
564	        Helpers.remap01(progress, revealStart, revealEnd),
565	      );
566	      const orbitX =
567	        Math.cos(Helpers.degToRad(pose.orbitAngleDeg)) * pose.orbitRadiusVmin;
568	      const orbitY =
569	        Math.sin(Helpers.degToRad(pose.orbitAngleDeg)) *
570	        pose.orbitRadiusVmin *
571	        MAIN_WHY_SHOWCASE.orbitVerticalScale;
572	      const orbitRotate = pose.orbitRotateDeg;
573	      const revealScale =
574	        pose.scale *
575	        this._easeOutBack(
576	          cardRevealProgress,
577	          MAIN_WHY_SHOWCASE.cardRevealOvershoot,
578	        );
579	
580	      const mergedX = Helpers.lerp(orbitX, pose.stackXvmin, mergeProgress);
581	      const mergedY = Helpers.lerp(orbitY, pose.stackYvmin, mergeProgress);
582	      const mergedRotate = Helpers.lerp(
583	        orbitRotate,
584	        pose.stackRotateDeg,
585	        mergeProgress,
586	      );
587	      const mergedScale = Helpers.lerp(
588	        revealScale,
589	        pose.scale * MAIN_WHY_SHOWCASE.cardMergeScaleFactor,
590	        mergeProgress,
591	      );
592	
593	      const x = Helpers.lerp(mergedX, pose.scatterXvmin, scatterProgress);
594	      const y = Helpers.lerp(mergedY, pose.scatterYvmin, scatterProgress);
595	      const rotate = Helpers.lerp(
596	        mergedRotate,
597	        pose.scatterRotateDeg,
598	        scatterProgress,
599	      );
600	      const scale = Helpers.lerp(
601	        mergedScale,
602	        pose.scale * MAIN_WHY_SHOWCASE.cardScatterScaleFactor,
603	        scatterProgress,
604	      );
605	      const opacity = Helpers.lerp(
606	        Helpers.lerp(
607	          MAIN_WHY_SHOWCASE.cardOpacityStart,
608	          MAIN_WHY_SHOWCASE.cardOpacityEnd,
609	          cardRevealProgress,
610	        ),
611	        MAIN_WHY_SHOWCASE.cardScatterOpacity,
612	        scatterProgress,
613	      );
614	
615	      card.style.setProperty("--about-who-card-x", `${x}vmin`);
616	      card.style.setProperty("--about-who-card-y", `${y}vmin`);
617	      card.style.setProperty("--about-who-card-rotate", `${rotate}deg`);
618	      card.style.setProperty("--about-who-card-scale", String(scale));
619	      card.style.setProperty("--about-who-card-opacity", String(opacity));
620	      card.style.setProperty("--about-who-card-z", String(pose.zIndex));
621	    });
622	  }
623	
624	  private _easeOutCubic(value: number): number {
625	    const clampedValue = Helpers.clamp01(value);
626	    return 1 - Math.pow(1 - clampedValue, 3);
627	  }
628	
629	  private _easeOutBack(value: number, overshoot: number): number {
630	    const clampedValue = Helpers.clamp01(value);
631	    const nextValue = clampedValue - 1;
632	    return (
633	      1 +
634	      (overshoot + 1) * Math.pow(nextValue, 3) +
635	      overshoot * Math.pow(nextValue, 2)
636	    );
637	  }
638	
639	  private _easeInOutCubic(value: number): number {
640	    const clampedValue = Helpers.clamp01(value);
641	    if (clampedValue < 0.5) {
642	      return 4 * clampedValue * clampedValue * clampedValue;
643	    }
644	    const nextValue = -2 * clampedValue + 2;
645	    return 1 - Math.pow(nextValue, 3) / 2;
646	  }
647	
648	  private _applyAboutHeroSloganKeywordVisualState(
649	    keywords: readonly HTMLElement[],
650	    activeStep: number,
651	  ): void {
652	    keywords.forEach((keyword, index) => {
653	      const isActive = index === activeStep;
654	      keyword.style.opacity = String(
655	        isActive
656	          ? ABOUT_HERO_SLOGAN.activeOpacity
657	          : ABOUT_HERO_SLOGAN.inactiveOpacity,
658	      );
659	      keyword.style.textShadow = isActive
660	        ? ABOUT_HERO_SLOGAN.activeTextShadow
661	        : ABOUT_HERO_SLOGAN.inactiveTextShadow;
662	    });
663	  }
664	
665	  private _animateAboutHeroSloganKeywordVisualState(
666	    keywords: readonly HTMLElement[],
667	    activeStep: number,
668	    gsap: GsapGlobal,
669	  ): void {
670	    keywords.forEach((keyword, index) => {
671	      const isActive = index === activeStep;
672	      gsap.killTweensOf?.(keyword);
673	      gsap.to(keyword, {
674	        opacity: isActive
675	          ? ABOUT_HERO_SLOGAN.activeOpacity
676	          : ABOUT_HERO_SLOGAN.inactiveOpacity,
677	        textShadow: isActive
678	          ? ABOUT_HERO_SLOGAN.activeTextShadow
679	          : ABOUT_HERO_SLOGAN.inactiveTextShadow,
680	        duration: ABOUT_HERO_SLOGAN.duration,
681	        ease: ABOUT_HERO_SLOGAN.ease,
682	        overwrite: true,
683	      });
684	    });
685	  }
