911	        this._contactFlowStage = "outtro";
912	        this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_LEAVING);
913	        await this._wait(CONTACT_THEATRE_DOM_EXIT_DELAY_MS);
914	        await this._playContactTheatreStep(
915	          this._engine,
