930	  private async _runContactIntroSequence(engine: Engine): Promise<void> {
931	    if (
932	      this._contactFlowStage === "ready" ||
933	      this._contactFlowStage === "outtro" ||
934	      this._contactFlowStage === "success"
935	    ) {
936	      return;
937	    }
938	    if (this._contactIntroTask) {
939	      await this._contactIntroTask;
940	      return;
941	    }
942	
943	    this._contactIntroTask = this._enqueueContactFlow(async () => {
944	      if (this._contactFlowStage !== "idle") return;
945	      this._contactFlowStage = "intro";
946	      this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_PENDING);
947	      try {
948	        await this._playContactTheatreStep(
949	          engine,
950	          () => this._pageTheatreBinder.startIntroIfNeeded(engine),
951	        );
952	      } catch (error) {
953	        this._contactFlowStage = "idle";
954	        this._syncContactDomState(null);
955	        throw error;
956	      }
957	      this._contactFlowStage = "ready";
958	      this._syncContactDomState(CONTACT_THEATRE_DOM_STATE_READY);
959	    }).finally(() => {
960	      this._contactIntroTask = null;
961	    });
962	
963	    await this._contactIntroTask;
964	  }
