1042	  private _syncContactDomMotion(state: ContactDomState | null): void {
1043	    this._clearContactMotionTimers();
1044	    const blocks = this._resolveContactRevealBlocks();
1045	    const successBlocks = this._resolveContactSuccessBlocks();
1046	    const successTextNodes = this._resolveContactSuccessTextNodes();
1047	    if (state === CONTACT_THEATRE_DOM_STATE_READY) {
1048	      this._setContactBlocksDown(successBlocks);
1049	      TextReveal.setVisibleOff(successTextNodes);
1050	      this._staggerContactBlocks(blocks, true);
1051	      return;
1052	    }
1053	    if (state === CONTACT_THEATRE_DOM_STATE_LEAVING) {
1054	      this._staggerContactBlocks([...blocks].reverse(), false);
1055	      TextReveal.setVisibleOff(successTextNodes);
1056	      return;
1057	    }
1058	    if (state === CONTACT_THEATRE_DOM_STATE_SUCCESS) {
1059	      successBlocks.forEach((block) => {
1060	        block.classList.remove("is-block-reveal-down");
1061	        BlockReveal.reveal(block);
1062	      });
1063	      this._staggerContactText(successTextNodes, true);
1064	      return;
1065	    }
1066	    if (state === CONTACT_THEATRE_DOM_STATE_PENDING) {
1067	      this._hideContactBlocksImmediately(blocks);
1068	      this._hideContactBlocksImmediately(successBlocks);
1069	      TextReveal.setVisibleOff(successTextNodes);
1070	      return;
1071	    }
1072	    this._hideContactBlocksImmediately(blocks);
1073	    this._hideContactBlocksImmediately(successBlocks);
1074	    TextReveal.setVisibleOff(successTextNodes);
1075	  }
